import heapq

def shortest_path(edges, start, end):
    # Validate edges for negative weights
    for _, _, weight in edges:
        if weight < 0:
            raise ValueError("Negative edge weight is not allowed.")

    # Handle case where start and end are the same node
    if start == end:
        return (0, [start])

    # Collect all nodes from edges
    all_nodes = set()
    for from_node, to_node, _ in edges:
        all_nodes.add(from_node)
        all_nodes.add(to_node)

    # Build adjacency list with edge weights
    graph = {}
    for from_node, to_node, weight in edges:
        if from_node not in graph:
            graph[from_node] = {}
        graph[from_node][to_node] = weight

    # Initialize distances
    distances = {node: float('inf') for node in all_nodes}
    distances[start] = 0

    # Priority queue: (distance, node)
    pq = [(0, start)]
    previous = {}

    while pq:
        current_dist, current_node = heapq.heappop(pq)

        if current_dist > distances[current_node]:
            continue

        if current_node == end:
            break

        if current_node not in graph:
            continue

        for neighbor, weight in graph[current_node].items():
            new_dist = current_dist + weight
            if new_dist < distances[neighbor]:
                distances[neighbor] = new_dist
                previous[neighbor] = current_node
                heapq.heappush(pq, (new_dist, neighbor))

    # Check if destination is reachable
    if end not in distances or distances[end] == float('inf'):
        return (None, None)

    # Reconstruct path from start to end
    path = []
    current = end
    while current != start:
        path.append(current)
        previous_node = previous.get(current)
        if previous_node is None:
            return (None, None)  # Break loop if no predecessor found
        current = previous_node

    path.append(start)
    path.reverse()

    return (distances[end], path)
